import React from 'react';
import { Card, CardContent, Stack, Typography, Button } from '@mui/material';
import AutoAwesomeIcon from '@mui/icons-material/AutoAwesome';
import { Link as RouterLink } from 'react-router-dom';

/**
 * Replaces the Carbon Q&A chat. Uncertainties are resolved by agents using
 * company profile and operations data — no interactive questionnaire.
 * Styled as an outlined card to match other carbon workspace panels.
 */
export default function CarbonAgentResolutionPanel() {
  return (
    <Card variant="outlined">
      <CardContent>
        <Stack spacing={1.25}>
          <Stack direction="row" spacing={1} alignItems="center">
            <AutoAwesomeIcon color="primary" fontSize="small" />
            <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
              Carbon agents resolve calculation uncertainties
            </Typography>
          </Stack>
          <Typography variant="body2" color="text.secondary">
            Sector, boundary, category, and functional-unit gaps are filled from your
            company profile and operations workflow when confidence is high.
            Upload clearer bills or update profile details when evidence is still required.
          </Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <Button
              component={RouterLink}
              to="/msme-profile"
              size="small"
              variant="outlined"
            >
              Open profile
            </Button>
            <Button
              component={RouterLink}
              to="/operations"
              size="small"
              variant="outlined"
            >
              Open operations
            </Button>
            <Button
              component={RouterLink}
              to="/document-upload"
              size="small"
              variant="text"
            >
              Upload bills
            </Button>
          </Stack>
        </Stack>
      </CardContent>
    </Card>
  );
}
